'use strict';

/*
 * Operational analytics and engagement data:
 *
 *   - metric definitions for the nine indicators the dashboard computes,
 *     plus one daily snapshot per indicator for every day of the window;
 *   - operational alerts and a management decision-card feed with evidence
 *     and follow-up actions;
 *   - the notification inbox, backed by message_outbox rows so the FK from
 *     `notifications.source_event_id` is always satisfied;
 *   - extra drug-interaction rules used by the prescribing safety check.
 *
 * Snapshot values are derived from the rows generated by the other modules so
 * the trend lines agree with the underlying appointments, encounters, labs,
 * inventory and payments.
 */

const {
  BRANCH_ID, USER, CURRENCY, NOW, WINDOW_START,
  txId, refId, chance, pick, int, dec, weighted,
  addDays, addMinutes, eachDay, localDate
} = require('./util');

function round2(value) { return Math.round(value * 100) / 100; }
function round6(value) { return Math.round(value * 1000000) / 1000000; }

// Lifecycle timestamps that are derived from a generated instant must never
// land in the future, otherwise the inbox and alert feed look inconsistent.
function clampPast(date) {
  const latest = addMinutes(NOW, -1);
  return date.getTime() <= latest.getTime() ? date : latest;
}

